    var ns = sum(mx.on);
    var rows = IV.map(function (r, i) { return { name: r[0], v: r[1], found: r[2], cnt: r[1].reduce(function (a, s, j) { return a + (mx.on[j] && s >= mx.min ? 1 : 0); }, 0), i: i }; }).sort(function (a, b) { return b.cnt - a.cnt || a.i - b.i; });
