    if (cpk) cpk.addEventListener('change', drawDec);
    drawDec();

    HH.chart('chart-ev', {
      type: 'line', data: { labels: DD.EV.map(function (e) { return e[0]; }), datasets: [{ label: 'Recorded events', data: DD.EV.map(function (e) { return e[1]; }), borderColor: BRASS, backgroundColor: alpha(BRASS, 0.18), fill: true, borderWidth: 2, pointRadius: 0, tension: 0.2 }] },
      options: { plugins: { legend: { display: false }, tooltip: { callbacks: { label: function (c) { return fmt(c.raw) + ' recorded events'; } } } }, scales: { x: Object.assign(axis({ grid: false }), { ticks: Object.assign({ maxTicksLimit: 8 }, tick) }), y: Object.assign(axis({ title: 'events per year' }), { min: 0, ticks: tick }) } }
    });

    var iB = function (y) { return DD.byr.indexOf(y); };
    var marks = DD.B.map(function (v, i) { return DD.byr[i] === 1970 || DD.byr[i] === 1991 || DD.byr[i] === 2007 ? v : null; });
    HH.chart('chart-bgd', {
      type: 'line', data: { labels: DD.byr, datasets: [
        { label: 'Deaths per 100,000', data: DD.B.map(function (v) { return v === null || v <= 0 ? null : v; }), borderColor: INKC, borderWidth: 1.6, pointRadius: 0, spanGaps: true, tension: 0 },
        { label: 'Bhola 1970 · 1991 · Sidr 2007', data: marks, borderColor: ROSE, backgroundColor: ROSE, showLine: false, pointRadius: 6, pointHoverRadius: 8 }] },
      options: { plugins: { legend: legB, tooltip: { callbacks: { label: function (c) { return c.dataset.label.split(' ')[0] === 'Deaths' ? fmt(c.raw, 2) + ' per 100,000' : 'marked storm: ' + fmt(c.raw, 1) + ' per 100,000'; } } } }, scales: { x: Object.assign(axis({ grid: false }), { ticks: Object.assign({ maxTicksLimit: 9 }, tick) }), y: Object.assign(axis({ title: 'per 100,000 (log scale)' }), { type: 'logarithmic', min: 0.01, max: 1000, ticks: Object.assign({ callback: function (v) { return [0.01, 0.1, 1, 10, 100, 1000].indexOf(v) >= 0 ? v : ''; } }, tick) }) } }
    });

    /* --- scorecard charts ------------------------------------------------------------------------------- */
    var qd = C.filter(function (c) { return c.gdp && c.prs !== null; });
    var xs = qd.map(function (c) { return Math.log(c.gdp); }), ys = qd.map(function (c) { return c.prs; });
    var mx_ = mean(xs), my_ = mean(ys), bx = sum(xs.map(function (x, i) { return (x - mx_) * (ys[i] - my_); })) / sum(xs.map(function (x) { return (x - mx_) * (x - mx_); })), ax = my_ - bx * mx_;
    var lo = Math.min.apply(null, qd.map(function (c) { return c.gdp; })), hi = Math.max.apply(null, qd.map(function (c) { return c.gdp; }));
